class METProcMetrics
{
    UtcDateTime                      dateTimeBegin;
    UtcDateTime                      lastDbWrite;
    int64                            dualWriteTimeStart, description2TimeStart, description3TimeStart, description4TimeStart, description5TimeStart, description6TimeStart, description7TimeStart, description8TimeStart, description9TimeStart, description10TimeStart;
    int64                            dualWriteTimeEnd, description2TimeEnd, description3TimeEnd, description4TimeEnd, description5TimeEnd, description6TimeEnd, description7TimeEnd, description8TimeEnd, description9TimeEnd, description10TimeEnd;
    Integer                          lineCount, documentCount, description2Count, description3Count, description4Count, description5Count, description6Count, description7Count, description8Count, description9Count, description10Count;
    Integer                          updateIntervalSec;
    int64                            totalDualWriteMs, totalDescription2Ms, totalDescription3Ms, totalDescription4Ms, totalDescription5Ms, totalDescription6Ms, totalDescription7Ms, totalDescription8Ms, totalDescription9Ms, totalDescription10Ms;
    RefRecId                         batchJobId;
    RefRecId                         logRecId;
    METBatchMonitoringLogParameters  logParams;
    METBatchMonitoringLog            log;
    Total                            totalCount;       
    NotesLine                        description, description2, description3, description4, description5, description6, description7, description8, description9, description10;
    boolean                          currentLogNotFound;
    boolean                          isTraceEnded;    

}

Method.Source:
public METBatchMonitoringLogParameters parmLogParams(METBatchMonitoringLogParameters _logParams = logParams)
{
    logParams = _logParams;
    return logParams;
}

public void startTrace(Total _totalCount, NotesLine _description)
{
    totalCount   = _totalCount;
    description  = _description;
    this.beginTrace();
}

public void startTraceFromQuery(QueryRun _queryRun, NotesLine _description)
{
    totalCount  = METGlobal::countTotalQuick(_queryRun);
    description = _description;
    this.beginTrace();
}

public METProcMetrics beginTrace(str _description = '')
{
    UserConnection  userConnection;
    ;
    if (_description)
    {
        description = _description;
    }

    batchJobId         = BatchHeader::getCurrentBatchTask().BatchJobId;
    dateTimeBegin      = DateTimeUtil::getSystemDateTime();
    updateIntervalSec  = logParams.UpdateIntervalSec > 0 ? logParams.UpdateIntervalSec : 5;
    lastDbWrite        = DateTimeUtil::minValue();
    userConnection     = new UserConnection();
    documentCount      = 0;
    lineCount          = 0;

    log.setConnection(userConnection);
    log.initValue();
    log.Operation           = logParams.LogOperation;
    log.StartDateTime       = dateTimeBegin;
    log.Status              = METBatchMonitoringStatus::Running;
    log.LinesToProcess      = totalCount;
    log.UserId              = curuserid();
    log.CompanyId           = curext();
    log.BatchJobId          = batchJobId;
    log.BatchTaskId         = BatchHeader::getCurrentBatchTask().RecId;
    log.setSession();
    log.LastUpdatedDateTime = dateTimeBegin;
    log.Details             = description;
    log.Details2            = description2;
    log.Details3            = description3;
    log.Details4            = description4;
    log.Details5            = description5;
    log.Details6            = description6;
    log.Details7            = description7;
    log.Details8            = description8;
    log.Details9            = description9;
    log.Details10           = description10;

    try
    {
        userConnection.ttsbegin();
        log.insert();
        userConnection.ttscommit();
        logRecId    = log.RecId;
        lastDbWrite = dateTimeBegin;
    }
    catch
    {

    }
    finally
    {
        userConnection.finalize();
    }

    return this;
}

public NotesLine parmDescription(NotesLine _description = description)
{
    description = _description;
    return description;
}

public void endTrace(METBatchMonitoringStatus _status = METBatchMonitoringStatus::Completed)
{
    UserConnection  userConnection;
    ;
    if (currentLogNotFound)
    {
        return;
    }

    userConnection = new UserConnection();
    log.clear();
    log.setConnection(userConnection);

    try
    {
        userConnection.ttsbegin();
        select forupdate firstonly log
            where log.RecId == logRecId;

        if (log.RecId)
        {
            log.EndDateTime         = DateTimeUtil::getSystemDateTime();
            log.Status              = _status;
            log.DocumentCount       = documentCount;
            log.LineCount           = lineCount;
            log.DualWriteTime       = totalDualWriteMs;
            log.Details             = description;
            log.Details2            = description2;
            log.Details3            = description3;
            log.Details4            = description4;
            log.Details5            = description5;
            log.Details6            = description6;
            log.Details7            = description7;
            log.Details8            = description8;
            log.Details9            = description9;
            log.Details10           = description10;
            log.Details2Time        = totalDescription2Ms;
            log.Details3Time        = totalDescription3Ms;
            log.Details4Time        = totalDescription4Ms;
            log.Details5Time        = totalDescription5Ms;
            log.Details6Time        = totalDescription6Ms;
            log.Details7Time        = totalDescription7Ms;
            log.Details8Time        = totalDescription8Ms;
            log.Details9Time        = totalDescription9Ms;
            log.Details10Time       = totalDescription10Ms;
            log.Details2Count       = description2Count;
            log.Details3Count       = description3Count;
            log.Details4Count       = description4Count;
            log.Details5Count       = description5Count;
            log.Details6Count       = description6Count;
            log.Details7Count       = description7Count;
            log.Details8Count       = description8Count;
            log.Details9Count       = description9Count;
            log.Details10Count      = description10Count;
            log.LastUpdatedDateTime = log.EndDateTime;
            log.Duration            = log.durationDisp();
            log.update();
        }
        else
        {
            currentLogNotFound = true;
        }
    }
    finally
    {
        userConnection.ttscommit();
        userConnection.finalize();
        isTraceEnded = true;
    }
}

public void incProcessedCountWithDocument(str _details = '', int64 _documentCount = 1, int64 _lineCount = 0)
{
    description = _details;
    this.incProcessedCount(_documentCount, _lineCount);
}

public void incProcessedCount(int64 _documentCount = 1, int64 _lineCount = 0)
{
    UtcDateTime             now;
    UserConnection          userConnection;
    ;
    if (currentLogNotFound)
    {
        return;
    }
    documentCount += _documentCount;
    lineCount     += _lineCount;

    now = DateTimeUtil::getSystemDateTime();

    if (DateTimeUtil::getDifference(now, lastDbWrite) < updateIntervalSec)
    {
        return;
    }

    userConnection = new UserConnection();
    log.clear();

    try 
    {
        log.setConnection(userConnection);
        userConnection.ttsbegin();
        select forupdate firstonly log
            where log.RecId == logRecId;

        if (log.RecId)
        {
            log.DocumentCount       = documentCount;
            log.LineCount           = lineCount;
            log.LastUpdatedDateTime = now;
            log.Details             = description;
            log.Duration            = log.durationDisp();       
            log.update();
        }
        else
        {
            currentLogNotFound = true;
        }

        lastDbWrite = now;
    }
    finally
    {
        userConnection.ttscommit();
        userConnection.finalize();
    }
}

public static METProcMetrics construct(METBatchLogOperation _logOperation)
{
    METBatchMonitoringLogParameters logParams = METBatchMonitoringLogParameters::find(_logOperation);
    METProcMetrics                  procMetrics;

    if (!logParams.RecId || !logParams.IsLogEnabled)
    {
        procMetrics = new METProcMetricsDummy();
    }
    else
    {
        procMetrics = new METProcMetrics();
        procMetrics.parmLogParams(logParams);
    }

    return procMetrics;
}

public void ttsCommitTrace()
{
    this.startDualWriteTime();
    ttscommit;
    this.endDualWriteTime();
}

public void endDualWriteTime()
{
    dualWriteTimeEnd  = System.DateTime::UtcNow.Ticks;
    totalDualWriteMs += (dualWriteTimeEnd - dualWriteTimeStart) / 10000;
}

